import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test("audit events are listed oldest first with actor and action", { tag: "@AUD-01" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const createRes = await member.post("/api/vendors", {
    data: {
      name: uniqueName("Audit Vendor"),
      category: "services",
      contact_email: `audit-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@acme-supply.com`,
    },
  });
  expect(createRes.status(), await createRes.text()).toBe(201);
  const vendor = await createRes.json();

  const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: {
        name: "w9.txt",
        mimeType: "text/plain",
        buffer: readFileSync(sample("w9.txt")),
      },
    },
  });
  expect(uploadRes.status(), await uploadRes.text()).toBe(201);

  // Act: extraction runs in the background, so wait for its audit event.
  let items: Array<{ action: string; actor: { email: string }; at: string }> = [];
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/audit`);
        expect(res.status(), await res.text()).toBe(200);
        items = ((await res.json()) as { items: typeof items }).items;
        return items.map((e) => e.action);
      },
      { timeout: 30_000 },
    )
    .toEqual(["vendor.created", "document.uploaded", "document.extracted"]);

  // Assert
  expect(items.map((e) => e.action)).toEqual([
    "vendor.created",
    "document.uploaded",
    "document.extracted",
  ]);
  for (const event of items) {
    expect(event.actor.email).toBe("member@northwind.test");
    expect(event.at).toBeTruthy();
    expect(Number.isNaN(Date.parse(event.at)), `invalid timestamp ${event.at}`).toBe(false);
  }
});
